 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    background = 0

    def dominant_nonzero(values):
        counts = {}
        for value in values:
            if value != background:
                counts[value] = counts.get(value, 0) + 1
        if not counts:
            return None, 0
        color = max(counts, key=counts.get)
        return color, counts[color]

    horizontal = []
    for r, row in enumerate(grid):
        color, count = dominant_nonzero(row)
        if color is not None and count > w / 2:
            horizontal.append((r, color))

    vertical = []
    for c in range(w):
        color, count = dominant_nonzero([grid[r][c] for r in range(h)])
        if color is not None and count > h / 2:
            vertical.append((c, color))

    out = [[background for _ in range(2 * len(vertical) + 1)]
           for _ in range(2 * len(horizontal) + 1)]
    for i, (r, color) in enumerate(horizontal):
        out[2 * i + 1] = [color for _ in out[2 * i + 1]]
    for j, (c, color) in enumerate(vertical):
        for rr in range(len(out)):
            out[rr][2 * j + 1] = color
    # Preserve the actual value where a horizontal and vertical stripe cross.
    for i, (r, _) in enumerate(horizontal):
        for j, (c, _) in enumerate(vertical):
            out[2 * i + 1][2 * j + 1] = grid[r][c]
    return out
